#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# Generated by @aphrody/m3-os-themes: M3-BunOS for GNOME (seed #8c6c88).
# Idempotent: the first run snapshots the current gsettings and ~/.config/gtk-4.0/gtk.css; re-running keeps the snapshot.
# Reversible: ./install-gnome.sh --uninstall restores it. Flags: --mode auto|light|dark, --icons <freedesktop theme dir>, --dry-run.
set -euo pipefail
NAME="M3-BunOS"
MODE="auto"
ICONS=""
UNINSTALL=0
DRY=0
while [ $# -gt 0 ]; do
  case "$1" in
    --mode) MODE="$2"; shift ;;
    --icons) ICONS="$2"; shift ;;
    --uninstall) UNINSTALL=1 ;;
    --dry-run) DRY=1 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
  shift
done
HERE="$(cd "$(dirname "$0")" && pwd)"
DATA="${XDG_DATA_HOME:-$HOME/.local/share}"
CONF="${XDG_CONFIG_HOME:-$HOME/.config}"
THEME_DIR="$DATA/themes/$NAME"
STATE="$DATA/m3-os-themes"
SNAP="$STATE/gnome-$NAME.env"
ICON_SNAP="$STATE/gnome-$NAME.icons"
ICON_BACKUP="$STATE/gnome-$NAME.icon-dir"
GTK4_CSS="$CONF/gtk-4.0/gtk.css"
MARK="m3-os-themes marker"

run() { if [ "$DRY" = 1 ]; then echo "[dry-run] $*"; else "$@"; fi; }
gget() { gsettings get "$1" "$2" 2>/dev/null || true; }
gset() { if [ "$(gsettings writable "$1" "$2" 2>/dev/null)" = true ]; then run gsettings set "$1" "$2" "$3"; fi; }

case "$MODE" in auto|light|dark) ;; *) echo "unknown mode: $MODE" >&2; exit 2 ;; esac
if [ -n "$ICONS" ] && [ "$UNINSTALL" = 0 ]; then
  [ -f "$ICONS/index.theme" ] || { echo "--icons: $ICONS has no index.theme" >&2; exit 2; }
  ICON_NAME="$(basename "$ICONS")"
  case "$ICON_NAME" in ""|.|..|*[!a-zA-Z0-9_.\ -]*) echo "invalid icon directory name: $ICON_NAME" >&2; exit 2 ;; esac
fi


if [ "$UNINSTALL" = 1 ]; then
  if [ -f "$SNAP" ]; then
    while IFS='=' read -r key value; do
      case "$key" in
        GTK_THEME) [ -z "$value" ] || gset org.gnome.desktop.interface gtk-theme "$value" ;;
        COLOR_SCHEME) [ -z "$value" ] || gset org.gnome.desktop.interface color-scheme "$value" ;;
        ACCENT) [ -z "$value" ] || gset org.gnome.desktop.interface accent-color "$value" ;;
        SHELL_THEME) [ -z "$value" ] || gset org.gnome.shell.extensions.user-theme name "$value" ;;
      esac
    done < "$SNAP"
  fi
  if [ -f "$ICON_SNAP" ]; then
    while IFS='=' read -r key value; do
      case "$key" in
        ICON_THEME_PREV) [ -z "$value" ] || gset org.gnome.desktop.interface icon-theme "$value" ;;
        ICON_NAME)
          case "$value" in ""|.|..|*[!a-zA-Z0-9_.\ -]*) echo "invalid icon snapshot name" >&2; exit 2 ;; esac
          run rm -rf "$DATA/icons/$value"
          if [ -e "$ICON_BACKUP" ]; then run cp -a "$ICON_BACKUP" "$DATA/icons/$value"; fi
          ;;
      esac
    done < "$ICON_SNAP"
    run rm -rf "$ICON_BACKUP"
    run rm -f "$ICON_SNAP"
  fi
  run rm -rf "$THEME_DIR"
  if [ -f "$GTK4_CSS" ] && grep -q "$MARK" "$GTK4_CSS"; then
    run rm -f "$GTK4_CSS"
    [ -f "$GTK4_CSS.m3bak" ] && run mv "$GTK4_CSS.m3bak" "$GTK4_CSS"
  fi
  run rm -f "$SNAP"
  echo "$NAME removed."
  exit 0
fi

if [ -n "$ICONS" ] && [ -f "$ICON_SNAP" ]; then
  while IFS='=' read -r key value; do
    if [ "$key" = ICON_NAME ] && [ "$value" != "$ICON_NAME" ]; then
      echo "uninstall before changing the installed icon directory" >&2; exit 2
    fi
  done < "$ICON_SNAP"
fi
run mkdir -p "$STATE" "$DATA/themes" "$CONF/gtk-4.0"
if [ ! -f "$SNAP" ] && [ "$DRY" = 0 ]; then
  {
    echo "GTK_THEME=$(gget org.gnome.desktop.interface gtk-theme)"
    echo "COLOR_SCHEME=$(gget org.gnome.desktop.interface color-scheme)"
    echo "ACCENT=$(gget org.gnome.desktop.interface accent-color)"
    echo "SHELL_THEME=$(gget org.gnome.shell.extensions.user-theme name)"
  } > "$SNAP"
fi

run rm -rf "$THEME_DIR"
run cp -r "$HERE/themes/$NAME" "$THEME_DIR"
if [ -f "$GTK4_CSS" ] && ! grep -q "$MARK" "$GTK4_CSS" && [ ! -f "$GTK4_CSS.m3bak" ]; then
  run cp "$GTK4_CSS" "$GTK4_CSS.m3bak"
fi
case "$MODE" in
  dark) run cp "$THEME_DIR/gtk-4.0/gtk-dark.css" "$GTK4_CSS" ;;
  *) run cp "$THEME_DIR/gtk-4.0/gtk.css" "$GTK4_CSS" ;;
esac

if [ -n "$ICONS" ]; then
  [ -f "$ICONS/index.theme" ] || { echo "--icons: $ICONS has no index.theme (bun packages/material-design-icons/scripts/export-theme.ts)" >&2; exit 2; }
  ICON_NAME="$(basename "$ICONS")"
  if [ ! -f "$ICON_SNAP" ] && [ "$DRY" = 0 ]; then
    if [ -e "$DATA/icons/$ICON_NAME" ]; then cp -a "$DATA/icons/$ICON_NAME" "$ICON_BACKUP"; fi
    { echo "ICON_THEME_PREV=$(gget org.gnome.desktop.interface icon-theme)"; echo "ICON_NAME=$ICON_NAME"; } > "$ICON_SNAP"
  fi
  run mkdir -p "$DATA/icons"
  run rm -rf "$DATA/icons/$ICON_NAME"
  run cp -r "$ICONS" "$DATA/icons/$ICON_NAME"
  command -v gtk-update-icon-cache >/dev/null 2>&1 && run gtk-update-icon-cache -q -t -f "$DATA/icons/$ICON_NAME" || true
  gset org.gnome.desktop.interface icon-theme "'$ICON_NAME'"
fi

gset org.gnome.desktop.interface gtk-theme "'$NAME'"
case "$MODE" in
  dark) gset org.gnome.desktop.interface color-scheme "'prefer-dark'"; ACC="pink" ;;
  light) gset org.gnome.desktop.interface color-scheme "'prefer-light'"; ACC="purple" ;;
  *) gset org.gnome.desktop.interface color-scheme "'default'"; ACC="purple" ;;
esac
gset org.gnome.desktop.interface accent-color "'$ACC'"
if gsettings list-schemas 2>/dev/null | grep -qx org.gnome.shell.extensions.user-theme; then
  gset org.gnome.shell.extensions.user-theme name "'$NAME'"
else
  echo "note: enable the User Themes extension to apply the Shell theme ($NAME)." >&2
fi
echo "$NAME applied ($MODE). Restore with: $0 --uninstall"
